/// <summary>
/// Coc for vendor invoice workflow event handler
/// </summary>
[ExtensionOf(classStr(VendInvoiceHeaderWorkflow))]
final class METVendInvoiceHeaderWorkflow_Extension
{
}

Method.Source:
    /// <summary>
    /// Activates the vendor invoice workflow.
    /// </summary>
    public void submit()
    {
        boolean metValid;
        str     metMessage;

        [metValid, metMessage] = VendInvoiceHeaderWorkflow::metValidateSubmissionForInvoiceMatching(vendInvoiceInfoTable);

        if(!metValid)
            throw error(metMessage);

        next submit();
    }

    /// <summary>
    /// Reactivates the vendor invoice header workflow.
    /// </summary>
    public void reSubmit()
    {
        boolean metValid;
        str     metMessage;

        [metValid, metMessage] = VendInvoiceHeaderWorkflow::metValidateSubmissionForInvoiceMatching(vendInvoiceInfoTable);

        if(!metValid)
            throw error(metMessage);

        next reSubmit();
    }

    /// <summary>
    /// validates if the vendor invoice can be submitted/resubmitted to workflow according to invoice matching requirements
    /// </summary>
    /// <param name = "_metVendInvoiceInfoTable">Vendor invoice</param>
    /// <returns>Container statement if valid and error message</returns>
    public static container metValidateSubmissionForInvoiceMatching(VendInvoiceInfoTable _metVendInvoiceInfoTable)
    {
        boolean     metValid = true;
        str         metMessage = '';

        if(!_metVendInvoiceInfoTable.purchTable().isInterCompanyOrder() && !_metVendInvoiceInfoTable.METClaimInvoice)
        {
            if(!_metVendInvoiceInfoTable.MetImportAmount)
            {
                metValid = false;
                metMessage = "@MET:NoInvAmtNoGST";
            }
            else if(_metVendInvoiceInfoTable.displayMetMatchStatus() == METMatchStatus::Fail)
            {
                metValid = false;
                metMessage = "@MET:MetMatchStatusFail";
            }
            else
            {
                if(_metVendInvoiceInfoTable.displayMetVariance() && !_metVendInvoiceInfoTable.displayMETVarInTolerance())
                {
                    metValid = false;
                    metMessage = "@MET:VarOutTol";
                }
            }
        }

        return [metValid, metMessage];
    }
